<?php require_once BASE_PATH.'/resources/views/inventory/components.php'; ?>
<div id="inventory-results"><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="surface table-scroll inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Product / SKU</th><th>Category</th><th>Brand / Compatible bikes</th><th>Stock</th><th>Minimum</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($listing['rows'] as $p): ?><tr><td data-label="Product"><?php if(can($user,'products.manage')): ?><a href="<?= e(url('/products/view')) ?>&amp;id=<?= (int)$p['id'] ?>"><strong><?= e($p['name']) ?></strong></a><?php else: ?><strong><?= e($p['name']) ?></strong><?php endif; ?><small><?= e($p['sku']) ?></small><small><?= e($p['part_number']??'') ?></small><?php if($p['match_info']): ?><small class="inventory-match">Matched: <?= e($p['match_info']) ?></small><?php endif; ?></td><td data-label="Category"><?= e($p['category_name']) ?><small><?= e($p['subcategory_name']??'') ?></small></td><td data-label="Brand / Compatible bikes"><?= e($p['brand_name']??'—') ?><small class="inventory-bike-summary"><?= e($p['bikes']??'No recorded bike mappings') ?></small></td><td data-label="Available stock"><?= $p['quantity']===null?'Not tracked':quantity($p['quantity']) ?></td><td data-label="Minimum"><?= quantity($p['reorder_level']) ?></td><td data-label="Status"><span class="<?= stockStatus($p)==='Low stock'?'stock-warning':'' ?>"><?= e(stockStatus($p)) ?></span><small><?= $p['archived_at']?'Archived product':e(ucfirst($p['status'])) ?></small></td><td data-label="Actions"><div class="inventory-row-actions"><?php inventoryActions((int)$p['id'],!$p['archived_at'] && $p['status']==='active'); ?><?php if(can($user,'inventory.movements')): ?><a class="button" href="<?= e(url('/inventory/movements')) ?>&amp;product_id=<?= (int)$p['id'] ?>">History</a><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table><?php if(!$listing['rows']): ?><div class="empty-state compact"><h3>No matching stock</h3><p>Change filters or add products through Product Management.</p></div><?php endif; ?></div><?php inventoryPager($listing,$filters,'/inventory'); ?>

</div>
